    max_heap = []
    for i in range(k):
        min_heap.append(tup[i])
        max_heap.append(tup[i])
    heapq.heapify(min_heap)
    heapq.heapify(max_heap)
    for i in range(k, len(tup)):
        if tup[i] < min_heap[0]:
            heapq.heappush(min_heap, tup[i])
            heapq.heappop(min_heap)
        if tup[i] > max_heap[0]:
            heapq.heappush(max_heap, tup[i])
            heapq.heappop(max_heap)
    return (min_heap, max_heap)

