def maximum_product(arr):
    if len(arr) < 3:
        return None
    heap = []
    for i in arr:
        heapq.heappush(heap, i)
    if len(heap) == 3:
        return heapq.heappop(heap) * heapq.heappop(heap) * heapq.heappop(heap)
    else:
        return heapq.heappop(heap) * heapq.heappop(heap) * heapq.heappop(heap) * heapq.heappop(heap)

