def coin_change(coins, amount):
    if amount == 0:
        return 0
    if amount < 0:
        return -1
    min_coins = float('inf')
    for coin in coins:
        subproblem = coin_change(coins, amount - coin)
        if subproblem >= 0 and subproblem < min_coins:
            min_coins = subproblem + 1
    return min_coins if min_coins!= float('inf') else -1

def max_height(root):
    if root is None:
        return 0
    return 1 + max(max_height(root.left), max_height(root.right))

